import{z as s,x as p,o as t,c as B,q as i,j as A,D as r,d as E,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"映射归约与不可判定","description":"","frontmatter":{"title":"映射归约与不可判定","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mapping-reduction-undecidable.md","filePath":"cs/mapping-reduction-undecidable.md","lastUpdated":1791413859000}'),m={name:"cs/mapping-reduction-undecidable.md"};function d(M,a,h,_,f,u){const n=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="映射归约与不可判定" tabindex="-1">映射归约与不可判定 <a class="header-anchor" href="#映射归约与不可判定" aria-label="Permalink to &quot;映射归约与不可判定&quot;">​</a></h1><div class="epigraph"><p>可计算函数 $f$ 满足 $x\\in A\\iff f(x)\\in B$，则 $B$ 可判定会带走 $A$；不可判定沿箭头向上游走。</p><footer>—— 据 Post；Sipser 整理</footer></div><p>上一课<a href="/cs/halting-diagonalization">对角化与停机</a>钉了 \\(A_{\\mathrm{TM}}\\) 与 \\(HALT\\)。缺口是传递：不必每次对角化。映射归约（many-one，\\(A\\le_m B\\)）是可计算性里的 Karp 箭头。主干<a href="/cs/np-reduction">多项式归约</a>已经练过方向；这里<strong>没有多项式限制</strong>，只要 \\(f\\) 可计算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>构造 \\(f\\)：实例变成实例，\\(x\\in A\\iff f(x)\\in B\\)。若 \\(B\\) 可判定，则 \\(A\\) 可判定（先算 \\(f\\) 再跑 \\(B\\) 的判定器）。逆否： \\(A\\) 不可判定 \\(\\Rightarrow\\) \\(B\\) 不可判定。RE 同样： \\(B\\) 可识别 \\(\\Rightarrow\\) \\(A\\) 可识别。方向与复杂度课相同，资源不同。</p><p><span class="marginnote">直觉类比：归约像「代加工」——假设有人会判 \\(B\\)，你把 \\(A\\) 的实例加工成 \\(B\\) 的实例转手一问，就等于会判 \\(A\\)。于是 \\(B\\) 可判定会抬升 \\(A\\) 可判定；反过来 \\(A\\) 已被钉死不可判定，箭头指向的 \\(B\\) 只能跟着不可判定。</span></p><p>例：空性 \\(E_{\\mathrm{TM}}=\\{\\langle M\\rangle\\mid L(M)=\\emptyset\\}\\)。从 \\(A_{\\mathrm{TM}}\\) 化来：给定 \\(\\langle M,w\\rangle\\)，造 \\(M&#39;\\) 忽略输入、模拟 \\(M\\) 于 \\(w\\)，接受则接受。\\(M\\) 接受 \\(w\\) iff \\(L(M&#39;)\\ne\\emptyset\\)。于是 \\(A_{\\mathrm{TM}}\\le_m \\overline{E_{\\mathrm{TM}}}\\)，\\(E_{\\mathrm{TM}}\\) 不可判定。</p><h3 id="映射归约不是-turing-归约" tabindex="-1">映射归约不是 Turing 归约 <a class="header-anchor" href="#映射归约不是-turing-归约" aria-label="Permalink to &quot;映射归约不是 Turing 归约&quot;">​</a></h3><p>Turing 归约允许问神谕多次。映射归约是一次、非自适应、保持「是/否」双向。更强的归约会把更多集合连起来；课堂不可判定清单用 \\(\\le_m\\) 足够。</p><p><span class="marginnote">直觉类比：Turing 归约像可以反复追问的顾问，问几次、看着答案接着问都行；映射归约像只能寄一封信——把问题加工好寄出去，换回一个「是/否」。只许寄一封是更严的限制，用它证出的不可判定也更干净。</span></p><p><span class="marginnote">Post 问题关心 RE 度。Sipser 用 \\(\\le_m\\) 贯穿第 5 章。本课不引入度论。与 Karp \\(\\le_p\\) 对照：同一箭头形状，函数类从多项式换成可计算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明 \\(B\\) 不可判定：从已知不可判定的 \\(A\\) 造 \\(f\\)。写清 \\(M&#39;\\) 做什么、为何可计算、为何当且仅当。常见模板：让 \\(M&#39;\\) 在「想要的语义」上模拟 \\(M(w)\\)，否则什么都不接受。</p>',13)),(t(),A(o,null,{default:r(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%20A%22%5D%20--%3E%7C%22f%20%E5%8F%AF%E8%AE%A1%E7%AE%97%22%7C%20B%5B%22%E9%97%AE%E9%A2%98%20B%22%5D%0A%20%20B%20--%3E%20DEC%5B%22%E8%8B%A5%20B%20%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A%20%20DEC%20--%3E%20IMP%5B%22%E5%88%99%20A%20%E5%8F%AF%E5%88%A4%E5%AE%9A%EF%BC%9A%E7%9F%9B%E7%9B%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"补：若 \\(A\\le_m B\\) 则 \\(\\overline A\\le_m\\overline B\\)。故 \\(E_{\\mathrm{TM}}\\) 的补可识别与否要另说——实际上 \\(E_{\\mathrm{TM}}\\) 不是 RE。点名即可。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"有了归约，不可判定对象批量生产：\\(EQ_{\\mathrm{TM}}\\)、是否有限、是否正则……下一课 Rice 一次打完「非平凡语义」。本课先掌握单次构造，避免 Rice 变成口号。",-1)),a[6]||(a[6]=e("p",null,"编码 \\(\\langle M\\rangle\\) 必须是可计算的标准编码；细节不影响存在性。",-1)),a[7]||(a[7]=e("p",null,[E("构造 \\(M'\\) 时要保证：无论 \\(M'\\) 的输入是什么（常忽略），其语言只取决于 \\(M\\) 在 \\(w\\) 上的行为。漏掉「忽略输入」会让归约随 \\(M'\\) 的输入变，当且仅当失败。RE 归约保持可识别；要证「不是 RE」，常化到 \\(E_{\\mathrm{TM}}\\) 或补 \\(A_{\\mathrm{TM}}\\)。方向与"),e("a",{href:"/cs/np-reduction"},"多项式归约"),E("相同，只是 \\(f\\) 不必多项式。")],-1)),(t(),A(o,null,{default:r(()=>[l(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%BB%99%E5%AE%9A%20A_TM%20%E5%AE%9E%E4%BE%8B%3A%20M%20%E4%B8%8E%20w%22%5D%20--%3E%20BUILD%5B%22%E9%80%A0%20M'%3A%20%E5%BF%BD%E7%95%A5%E8%87%AA%E5%B7%B1%E7%9A%84%E8%BE%93%E5%85%A5%22%5D%0A%20%20BUILD%20--%3E%20SIM%5B%22%E5%9C%A8%20M'%20%E5%86%85%E9%83%A8%E6%A8%A1%E6%8B%9F%20M%20%E4%BA%8E%20w%22%5D%0A%20%20SIM%20--%3E%20ACC%7B%22M%20%E6%8E%A5%E5%8F%97%20w%3F%22%7D%0A%20%20ACC%20--%3E%7C%22%E6%98%AF%22%7C%20YES%5B%22M'%20%E6%8E%A5%E5%8F%97%3A%20L(M')%20%E9%9D%9E%E7%A9%BA%22%5D%0A%20%20ACC%20--%3E%7C%22%E5%90%A6%E6%88%96%E4%B8%8D%E5%81%9C%22%7C%20NO%5B%22M'%20%E4%BB%80%E4%B9%88%E9%83%BD%E4%B8%8D%E6%8E%A5%E5%8F%97%3A%20L(M')%20%E4%B8%BA%E7%A9%BA%22%5D%0A%20%20YES%20--%3E%20EQ%5B%22L(M')%20%E9%9D%9E%E7%A9%BA%20%E5%BD%93%E4%B8%94%E4%BB%85%E5%BD%93%20M%20%E6%8E%A5%E5%8F%97%20w%22%5D%0A%20%20NO%20--%3E%20EQ%0A%20%20EQ%20--%3E%20RED%5B%22%E6%95%85%20A_TM%20%E2%89%A4m%20%E9%9D%9E%E7%A9%BA%E6%80%A7%2C%20E_TM%20%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">常见误区：初学者造 \\(M&#39;\\) 常忘了让它忽略自己的输入。一旦 \\(L(M&#39;)\\) 随 \\(M&#39;\\) 的输入变，「\\(M\\) 接受 \\(w\\) 当且仅当 \\(L(M&#39;)\\) 非空」这条桥就断了——空性例的内容必须完全由 \\(M\\) 在 \\(w\\) 上的行为决定，与谁来运行 \\(M&#39;\\) 无关。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Rice，不引入算术层级的完整归约。不把 \\(\\le_p\\) 的 NPC 证明搬过来——那是复杂性单元。后课默认：传递不可判定用 \\(\\le_m\\)，箭头方向与<a href="/cs/np-reduction">多项式归约</a>相同。下一课语义性质。</p><p>归约函数必须对所有实例可计算且总停：用停机问题当 \\(f\\) 的内部会把归约写废。箭头画反则证到了错误的那一侧。Rice 下一课把模板批量应用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(A\\le_m B\\)：可计算 \\(f\\) 保持成员；难度向上游。</li><li>从 \\(A_{\\mathrm{TM}}\\) 构造 \\(M&#39;\\) 是标准手法。</li><li>无时间限制；不是 Karp 归约的复述，但方向相同。</li><li>出处：Post；Sipser。</li></ul>',6))])}const D=s(m,[["render",d]]);export{T as __pageData,D as default};
